insert into public.ukweli_knowledge (slug, topic, question, keywords, answer, language, source, source_url, sensitive, sort_order, resources) values
('bodies-vary-sw','body-image',$q$Kuna tatizo na jinsi sehemu zangu za siri zinavyoonekana?$q$,
 array['kawaida','kuma','uume','inaonekanaje','ukubwa','mbaya','ndogo'],
 $q$Hakuna "kawaida" moja — kuma, midomo ya uke, uume, matiti na rangi ya ngozi vinakuja kwa maumbo, ukubwa na rangi tofauti, na mara nyingi kinachoonekana "kizuri kabisa" mtandaoni kimehaririwa au kubadilishwa. Midomo iliyolegea au isiyolingana, pumbu moja kuwa chini ya lingine, uume uliopinda kidogo, ngozi nyeusi kuzunguka sehemu za siri, au matiti ya ukubwa tofauti — yote ni ya kawaida na yenye afya. Kinachohitaji kuonana na daktari ni mabadiliko unayoweza kuhisi au kuona — uvimbe mpya, kidonda, majimaji yasiyo ya kawaida, harufu kali, kuwashwa au maumivu — kwa sababu hayo yaweza kuwa maambukizi yanayotibika. LA KUFANYA: kama kuna kinachokutia wasiwasi au kubadilika, muone muuguzi kwenye kliniki rafiki kwa vijana, uliza hapa Ukweli, au piga LVCT One2One bila malipo kwa 1190. Kuonekana tofauti sio kasoro; ni mwili tu.$q$,'sw','WHO','https://www.who.int/health-topics/sexual-health',false,10,$j$[{"k": "app", "label": "Pata kliniki", "v": "#fika"}, {"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "link", "label": "WHO: afya ya ngono", "v": "https://www.who.int/health-topics/sexual-health"}]$j$::jsonb),

('masturbation-safe-sw','masturbation',$q$Je, kujichua kutaniumiza?$q$,
 array['kujichua','punyeto','kujigusa','masturbation'],
 $q$Hapana — kujichua ni kawaida na hakuna madhara kiafya. Hakusababishi upofu, ugumba, udhaifu, chunusi, "kupoteza nguvu", wala ugonjwa wowote, hakuna hatari ya mimba wala magonjwa ya zinaa, na kwaweza kukusaidia kuelewa mwili wako, kupunguza msongo na kulala vizuri. Kufanya mara kwa mara ni sawa; hakuna "kupita kiasi" ilimradi hakukuumizi wala kukuzuia shule, marafiki au majukumu. LA KUFANYA: kama kutaanza kuhisi kama uraibu, au unakitumia tu kukimbia msongo, ni vyema kuzungumza na mshauri wa shule, mtu mzima unayemwamini, au LVCT One2One (1190, bila malipo na kwa siri). Chochote ulichoambiwa kukutisha, hakuna uchafu ndani yake.$q$,'sw','WHO','https://www.who.int/health-topics/sexual-health',false,20,$j$[{"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "app", "label": "Uliza kwa siri", "v": "#ask"}]$j$::jsonb),

('sexual-feelings-normal-sw','sexual-feelings',$q$Ni kawaida kuhisi hamu ya ngono mara kwa mara?$q$,
 array['hamu','ashiki','hisia za ngono','nyege'],
 $q$Kuhisi mvuto, ashiki, udadisi au hamu kali — wakati mwingine ghafla — ni sehemu ya kawaida ya kubalehe, inayoendeshwa na homoni na ni ya kibinadamu kabisa. Hisia hizi huja na kuondoka, zaweza kuwa kuhusu watu usingewahi kuwafikia, na hazikufanyi mtu mbaya au mchafu. Jambo muhimu ni kwamba hisia na vitendo ni tofauti: una uhuru daima wa kuchagua unachofanya, lini na na nani — au kutofanya kabisa. LA KUFANYA: kama hisia zitakulemea au kukuchanganya, zungumza na mtu mzima unayemwamini, mshauri wa shule, au LVCT One2One (1190, bila malipo na kwa siri), au uliza hapa Ukweli. Hakuna "umri sahihi" wa kuhisi hivi na hakuna aibu.$q$,'sw',null,null,false,30,$j$[{"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "app", "label": "Uliza kwa siri", "v": "#ask"}]$j$::jsonb),

('same-sex-feelings-sw','identity',$q$Nina hisia kwa mtu wa jinsia yangu — kuna tatizo nami?$q$,
 array['mashoga','wasagaji','jinsia moja','jinsia yangu'],
 $q$Hakuna tatizo, hukuharibika wala hukutenda dhambi — kuvutiwa na jinsia yako, na jinsia zaidi ya moja, au kutokuwa na uhakika ni sehemu ya hali ya kawaida ya binadamu ambayo mamilioni hushiriki. Huna haja ya kujibandika lebo, "kuthibitisha" lolote, kujitangaza, au kufanya uamuzi sasa; hisia zaweza kuwa wazi au za kutatanisha na zaweza kubadilika, na yote ni sawa. Unachohisi ni halisi na halali hata kama watu hawakuelewi. LA KUFANYA: chagua kwa uangalifu unayemweleza, na kwa nafasi ya faragha isiyohukumu zungumza na mshauri au piga LVCT One2One (1190). Mtu akikutisha, akikufichua au kukudhuru kwa sababu hiyo, sio sawa — piga Childline 116 (bila malipo, saa 24, ukiwa chini ya miaka 18) au simu ya GBV 1195. Hauko peke yako na unastahili heshima na usalama.$q$,'sw',null,null,true,40,$j$[{"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "call", "label": "Childline 116", "v": "116"}, {"k": "call", "label": "Simu ya GBV 1195", "v": "1195"}]$j$::jsonb),

('gender-identity-sw','identity',$q$Vipi kama sihisi kuwa mvulana au msichana kikamilifu?$q$,
 array['jinsia','utambulisho','mvulana au msichana','trans'],
 $q$Utambulisho wa kijinsia ni hisia yako ya ndani ya kuwa mvulana, msichana, vyote, hakuna, au mahali katikati — na kwa baadhi haulingani na jinsia uliyopewa wakati wa kuzaliwa, ambalo ni uzoefu halisi wa kibinadamu uliotambuliwa kwa muda mrefu, sio mtindo wala ugonjwa. Waweza kuhisi hivi kwa nguvu au kuwa unajiuliza tu, na vyote ni sawa; hakuna muda uliowekwa wala kitu lazima uamue leo. Kuhisi hivi hakumaanishi kuna kitu kibaya nawe. LA KUFANYA: kwa kuwa si kila mtu ataelewa, fikiria ni nani salama kuzungumza naye na uende kwa kasi yako; mshauri rafiki kwa vijana — au LVCT One2One (1190) — aweza kukupa nafasi ya faragha isiyohukumu. Ukidhulumiwa au kutishiwa, Childline 116 (chini ya 18) na simu ya GBV 1195 zaweza kusaidia. Hisia zako ni halali.$q$,'sw',null,null,true,50,$j$[{"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "call", "label": "Childline 116", "v": "116"}]$j$::jsonb),

('sharing-toys-sw','safer-sex',$q$Ni salama kushiriki vifaa vya ngono au strap-on?$q$,
 array['kifaa cha ngono','strap on','vibrator','kushiriki vifaa'],
 $q$Kushiriki vifaa vya ngono kwaweza kusambaza magonjwa ya zinaa (herpes, HPV, kisonono, klamidia, homa ya ini) na kuvuruga uwiano unaosababisha maambukizi kama BV na fangasi, kwa sababu majimaji hubaki kwenye kifaa. Salama zaidi ni kutoshiriki; ukishiriki, vaa kondomu mpya kwenye kifaa na ibadilishe kwa kila mtu, osha kifaa kwa maji ya uvuguvugu na sabuni, ikauke, kati ya matumizi, na kamwe usikihamishe kutoka haja kubwa kwenda ukeni au mdomoni bila kusafisha na kubadilisha kondomu. Tumia lubricant ya maji au silicone, na vifaa salama kwa mwili (non-porous). LA KUFANYA: kama umeshiriki na una wasiwasi, pima STI kwenye kliniki rafiki kwa vijana, Marie Stopes Kenya (0800 720 005), au uliza LVCT One2One (1190) — magonjwa mengi hayana dalili lakini yanatibika. Kanuni hizi hufanya kila ngono kuwa salama zaidi.$q$,'sw','WHO','https://www.who.int/health-topics/sexually-transmitted-infections',true,60,$j$[{"k": "app", "label": "Pata kliniki", "v": "#fika"}, {"k": "call", "label": "Marie Stopes", "v": "0800720005"}, {"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "link", "label": "WHO: magonjwa ya zinaa", "v": "https://www.who.int/health-topics/sexually-transmitted-infections"}]$j$::jsonb),

('drugs-and-sex-sw','harm-reduction',$q$Ni hatari kuchanganya pombe au dawa za kulevya na ngono?$q$,
 array['kulewa','dawa za kulevya','pombe','bangi'],
 $q$Kuchanganya pombe au dawa na ngono huongeza hatari: kuwa umelewa au umepiga dawa hupotosha uamuzi, hivyo watu huruka kondomu, hukosea hali na hujuta — na muhimu zaidi, mtu aliyelewa sana hawezi kutoa ridhaa ya kweli, maana yake ngono naye si sawa, na kanuni hiyo inakulinda wewe pia. Mchanganyiko fulani ni hatari kimwili (pombe au dawa na vidonge vya nguvu, au kuchanganya dawa za usingizi). KUPUNGUZA MADHARA: ukinywa au ukatumia, beba kondomu, linda kinywaji chako, kaa na watu unaowaamini, kubaliana mipaka mapema, na kumbuka waweza kusimama wakati wowote. LA KUFANYA: kama kitu kilitokea ukiwa umelewa — ngono bila kinga au usiyoikubali — kliniki yaweza kutoa kidonge cha dharura na PEP (ndani ya saa 72); kwa dhuluma piga GBV 1195 au polisi 999, na kuzungumza piga One2One 1190. Hudaiwi ngono kwa sababu ulinunuliwa vinywaji.$q$,'sw',null,null,false,70,$j$[{"k": "call", "label": "Simu ya GBV 1195", "v": "1195"}, {"k": "call", "label": "One2One 1190", "v": "1190"}]$j$::jsonb),

('anal-sex-safety-sw','safer-sex',$q$Ngono ya njia ya haja kubwa ni salama?$q$,
 array['njia ya nyuma','anal','haja kubwa'],
 $q$Ngono ya njia ya haja kubwa yaweza kufanywa salama zaidi, lakini ina hatari kubwa zaidi ya HIV na STI kuliko aina nyingine, kwa sababu utando ni mwembamba na huchanika kwa urahisi. Kupunguza hatari: tumia kondomu daima na lubricant ya maji au silicone kwa wingi (sehemu hii haitengenezi ulainisho wake), nenda polepole, simama kukiwa na maumivu au damu; kamwe usiende kutoka haja kubwa kwenda ukeni bila kubadilisha kondomu, na usifanye douche — huwasha utando na huongeza hatari. Kondomu ni muhimu pia kwa sababu shahawa ikifika ukeni yaweza kuleta mimba. LA KUFANYA: kama unafanya hivi, uliza kliniki rafiki, VCT au NASCOP kuhusu PrEP na vipimo vya mara kwa mara, au piga One2One 1190 — na kama kondomu ilipasuka, PEP ndani ya saa 72 bado yaweza kuzuia HIV.$q$,'sw','NASCOP','https://www.nascop.or.ke',true,80,$j$[{"k": "app", "label": "Pata kliniki", "v": "#fika"}, {"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "link", "label": "NASCOP", "v": "https://www.nascop.or.ke"}]$j$::jsonb),

('what-is-consent-sw','consent',$q$Ni nini hasa huhesabika kama ridhaa?$q$,
 array['ridhaa','shinikizo','lazimisha','ubakaji','ndio'],
 $q$Ridhaa ni "ndiyo" iliyo wazi, ya hiari na ya shauku — nayo huhesabika tu pale mtu akiwa na akili timamu, macho, umri wa kutosha, na bila shinikizo, vitisho au hofu. Ni mahususi (ndiyo kwa jambo moja sio kwa yote), inaendelea (waweza kubadilisha nia wakati wowote), na inahitajika kila mara, hata na mpenzi au mwenzi wa ndoa. Ukimya, kukubali tu, au "ndiyo" ya kulazimishwa sio ridhaa. HAKI ZAKO: ngono bila ridhaa ni kosa Kenya chini ya Sheria ya Makosa ya Kujamiiana ya 2006 (Sexual Offences Act 2006), na ngono na mtu chini ya miaka 18 ni ubakaji wa mtoto (defilement), bila kujali "makubaliano". LA KUFANYA: kama hili limekutokea, sio kosa lako — nenda kliniki au hospitali haraka (ndani ya saa 72 wanaweza kutoa PEP na kidonge cha dharura na kujaza fomu za PRC na P3 za ushahidi), piga GBV 1195, Childline 116 ukiwa chini ya 18, au polisi 999. Msaada upo, na kuripoti ni chaguo lako.$q$,'sw',null,null,false,90,$j$[{"k": "call", "label": "Simu ya GBV 1195", "v": "1195"}, {"k": "call", "label": "Childline 116", "v": "116"}, {"k": "call", "label": "Polisi 999", "v": "999"}, {"k": "app", "label": "Pata kliniki", "v": "#fika"}]$j$::jsonb),

('after-unprotected-sex-sw','emergency',$q$Nimefanya ngono bila kinga — nifanye nini sasa?$q$,
 array['bila kinga','kondomu ilipasuka','kuzuia mimba','pep','p2','postinor'],
 $q$Tenda haraka — njia zako hufanya kazi vizuri ndani ya saa chache. KUZUIA MIMBA: kidonge cha dharura (kinauzwa Kenya bila cheti kwenye maduka ya dawa kama P2, Postinor-2 au Ecee-2) hufanya kazi vizuri ndani ya saa 72; aina fulani na kitanzi cha shaba (kinawekwa kliniki) hadi saa 120 (siku 5) — mapema ni bora. KUZUIA HIV: PEP ni dawa za kozi fupi ambazo lazima zianze ndani ya saa 72 — nenda hospitali, kituo cha afya au VCT uombe kwa jina. PA KWENDA: duka lolote la dawa kwa kidonge cha dharura; VCT, hospitali au Marie Stopes Kenya (0800 720 005) kwa PEP, EC na vipimo vya STI; au piga LVCT One2One (1190) au NASCOP Ushauri (0800 724 848). Kama hedhi itachelewa, pima mimba baada ya majuma matatu. Huhitaji ruhusa ya mzazi kuuliza.$q$,'sw','NASCOP','https://www.nascop.or.ke',false,100,$j$[{"k": "app", "label": "Pata kliniki", "v": "#fika"}, {"k": "call", "label": "Marie Stopes", "v": "0800720005"}, {"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "call", "label": "NASCOP Ushauri", "v": "0800724848"}]$j$::jsonb),

('protect-from-hiv-sw','hiv',$q$Nawezaje kujikinga na HIV?$q$,
 array['hiv','prep','kujikinga','ukimwi','u=u'],
 $q$Una njia kadhaa imara, na kuchanganya hufanya kazi vizuri. Kondomu ukitumia vizuri kila mara ni bora sana na pia huzuia STI nyingine na mimba. PrEP — kidonge cha kila siku kinachotolewa bure kupitia kliniki za NASCOP — kinaweza kuzuia HIV kabla ya kuathiriwa kama uko katika hatari zaidi. Ukiathiriwa, PEP iliyoanza ndani ya saa 72 bado yaweza kuzuia maambukizi. Na U=U: mtu anayeishi na HIV mwenye kiwango cha virusi kisichoonekana hawezi kuambukiza kingono. PA KWENDA: pata kupima bure na kwa siri (au kifaa cha kujipima kutoka duka la dawa) na uliza kuhusu PrEP kwenye kliniki rafiki kwa vijana au VCT; kwa maswali piga LVCT One2One (1190) au NASCOP Ushauri (0800 724 848). Kujua hali yako ni haraka na bure.$q$,'sw','NASCOP','https://www.nascop.or.ke',false,110,$j$[{"k": "app", "label": "Pata kliniki", "v": "#fika"}, {"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "call", "label": "NASCOP Ushauri", "v": "0800724848"}, {"k": "link", "label": "NASCOP", "v": "https://www.nascop.or.ke"}]$j$::jsonb),

('am-i-pregnant-sw','pregnancy',$q$Nitajuaje kama nina mimba?$q$,
 array['mimba','sijaona hedhi','kipimo cha mimba','hedhi imechelewa'],
 $q$Dalili ya kwanza ni hedhi kukosekana au kuchelewa sana, pengine na matiti kuuma, kichefuchefu, uchovu, kukojoa mara nyingi, au matone kidogo — lakini msongo, ugonjwa na homoni vyaweza kusababisha haya, hivyo dalili peke yake hazithibitishi. Njia pekee ya uhakika ni kipimo: vifaa vya mkojo ni rahisi katika duka lolote la dawa Kenya, na ni sahihi zaidi kuanzia siku hedhi inapotarajiwa (au majuma matatu baada ya ngono bila kinga); tumia mkojo wa asubuhi, na kama ni hasi lakini hedhi haiji, pima tena baada ya juma. LA KUFANYA: jibu lolote, kliniki rafiki kwa vijana au Marie Stopes Kenya (0800 720 005) yaweza kukueleza chaguo zako kwa faragha na bila hukumu, na LVCT One2One (1190) iko kukusikiliza. Hauko peke yako.$q$,'sw',null,null,false,120,$j$[{"k": "app", "label": "Pata kliniki", "v": "#fika"}, {"k": "call", "label": "Marie Stopes", "v": "0800720005"}, {"k": "call", "label": "One2One 1190", "v": "1190"}]$j$::jsonb),

('porn-vs-reality-sw','media',$q$Je, ngono halisi ni kama ninayoiona kwenye ponografia?$q$,
 array['ponografia','ngono kama','xvideos','taarifa halisi'],
 $q$Hapana — ponografia ni burudani iliyotengenezwa, sio uhalisia. Waigizaji huchaguliwa kwa sura, matukio huandikwa, huwekewa mwanga na kuhaririwa, miili hubadilishwa kwa upasuaji, na "uvumilivu" ni makato na wakati mwingine dawa. Ngono halisi ni ya polepole, ya aibu kidogo, ya kimya na yenye tofauti — miili ya kawaida, si kila mtu hufika kileleni, na ridhaa na mazungumzo ambayo ponografia huruka ndiyo hufanya iwe nzuri. PA KUPATA TAARIFA SAHIHI: kwa taarifa sahihi na bila aibu kuhusu mwili, ngono, ridhaa na mahusiano, uliza hapa Ukweli, zungumza na muuguzi au mshauri kwenye kliniki rafiki kwa vijana, au piga LVCT One2One bila malipo kwa 1190; vyanzo vya kuaminika ni kurasa za afya ya ngono za WHO. Jihadhari na "wataalamu" wa mitandao — kliniki ya kweli haitakuhukumu wala kukudanganya.$q$,'sw',null,null,false,130,$j$[{"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "app", "label": "Uliza kwa siri", "v": "#ask"}, {"k": "link", "label": "WHO: afya ya ngono", "v": "https://www.who.int/health-topics/sexual-health"}]$j$::jsonb),

('pressured-for-nudes-sw','safety',$q$Mtu ananisukuma nimtumie picha za uchi.$q$,
 array['picha za uchi','nudes','kutuma picha','sextortion','kuripoti'],
 $q$Humdai mtu yeyote picha — si mpenzi, si mkubwa, si anayeahidi mapenzi, pesa au siri — na heshima ya kweli ni kusikia "hapana" mara ya kwanza. Picha ikiondoka kwenye simu unapoteza udhibiti wote, hata kwenye programu za "kujifuta". NI KOSA LA JINAI: kusukuma, kutishia au kusambaza picha za faragha za mtu Kenya ni kosa chini ya Sheria ya Matumizi Mabaya ya Kompyuta na Uhalifu wa Mtandao ya 2018 (Computer Misuse and Cybercrimes Act 2018), na mtoto akihusika pia chini ya Sexual Offences Act 2006 na Children Act — aliyefanya ndiye kosa, sio wewe, hata kama ulituma kitu awali. LA KUFANYA: usitume zaidi na usilipe (kulipa huleta madai zaidi); hifadhi screenshots kama ushahidi, mzuie, na ripoti — piga Childline 116 (bila malipo, saa 24, ukiwa chini ya 18), au ripoti kwenye kituo chochote cha polisi au DCI (kitengo cha uhalifu wa mtandao); kwa msaada piga GBV 1195. Una haki ya kusema hapana na haki ya kupata msaada.$q$,'sw',null,null,false,140,$j$[{"k": "call", "label": "Childline 116", "v": "116"}, {"k": "call", "label": "Simu ya GBV 1195", "v": "1195"}, {"k": "app", "label": "Uliza kwa siri", "v": "#ask"}]$j$::jsonb)
