insert into public.ukweli_knowledge (slug, topic, question, keywords, answer, language, source, source_url, sensitive, sort_order, resources) values
('bodies-vary-sh','body-image',$q$Kuna shida na vile sehemu zangu za siri zinaonekana?$q$,
 array['kawaida','kuma','mboro','inaonekanaje','size','mbaya'],
 $q$Hakuna "normal" moja — kuma, lips za uke, mboro, maziwa na rangi ya ngozi zinakuja na shapes, size na rangi tofauti, na mob ya vile vitu zina-look "perfect" online zime-edit. Lips zimelegea ama hazilingani, pumbu moja iko chini ya ingine, mboro imepinda kidogo, ngozi nyeusi around sehemu za siri, ama maziwa za size tofauti — zote ni kawaida na healthy. Kitu inahitaji uone daktari ni change unaweza feel ama ona — lump mpya, kidonda, discharge ngeni, harufu kali, kuwashwa ama maumivu — sababu hizo zinaweza kuwa infection inatibika. KITU YA KUFANYA: kama kuna kitu inakustress ama imebadilika, ona nurse kwa clinic friendly kwa vijana, uliza hapa Ukweli, ama piga LVCT One2One free kwa 1190. Kuonekana different si kasoro; ni mwili tu.$q$,'sheng','WHO','https://www.who.int/health-topics/sexual-health',false,10,$j$[{"k": "app", "label": "Pata clinic", "v": "#fika"}, {"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "link", "label": "WHO: sexual health", "v": "https://www.who.int/health-topics/sexual-health"}]$j$::jsonb),

('masturbation-safe-sh','masturbation',$q$Je, kujichua kutaniumiza?$q$,
 array['kujichua','punyeto','masturbation','kujiguza'],
 $q$Hapana — kujichua ni kawaida na hakuna madhara ki-afya. Haileti upofu, ugumba, udhaifu, pimples, "kupoteza nguvu" wala ugonjwa, hakuna risk ya mimba ama STI, na inaweza kusaidia ujue mwili wako, u-relax na ulale poa. Kufanya mara kwa mara ni sawa; hakuna "too much" ilimradi haikuumizi wala haiku-stop shule, marafiki ama majukumu. KITU YA KUFANYA: ikianza ku-feel kama addiction, ama unaitumia tu ku-escape stress, ni poa kuongea na counsellor wa shule, mtu mzima una-trust, ama LVCT One2One (1190, free na confidential). Chochote uliambiwa ukuogopeshwe, hakuna uchafu ndani yake.$q$,'sheng','WHO','https://www.who.int/health-topics/sexual-health',false,20,$j$[{"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "app", "label": "Uliza kwa siri", "v": "#ask"}]$j$::jsonb),

('sexual-feelings-normal-sh','sexual-feelings',$q$Ni kawaida kuhisi nyege mara kwa mara?$q$,
 array['nyege','hamu','feelings za ngono','horny'],
 $q$Kuhisi attraction, nyege, curiosity ama hamu kali — wakati zingine ghafla — ni part ya kawaida ya ku-grow, inaendeshwa na hormones na ni ki-binadamu kabisa. Hizi feelings zinakuja na kuenda, zinaweza kuwa kuhusu watu usingewahi approach, na hazikufanyi mtu mbaya. Kitu muhimu ni kuwa feelings na actions ni tofauti: una freedom daima ku-choose unafanya nini, lini na na nani — ama kutofanya. KITU YA KUFANYA: kama feelings zina-overwhelm ama zina-confuse, ongea na mtu mzima una-trust, counsellor wa shule, ama LVCT One2One (1190, free na confidential), ama uliza hapa Ukweli. Hakuna "right age" ya kufeel hivi na hakuna aibu.$q$,'sheng',null,null,false,30,$j$[{"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "app", "label": "Uliza kwa siri", "v": "#ask"}]$j$::jsonb),

('same-sex-feelings-sh','identity',$q$Niko na feelings kwa mtu wa jinsia yangu — kuna shida na mimi?$q$,
 array['gay','lesbian','same sex','queer','jinsia moja'],
 $q$Hakuna shida, hukuharibika wala hukutenda dhambi — ku-attracted na jinsia yako, na jinsia zaidi ya moja, ama kutokuwa sure ni part ya hali ya kawaida ya binadamu ambayo millions wana-share. Huna haja ya ku-label, "ku-prove" kitu, ku-come out, ama kufanya decision sahii; feelings zinaweza kuwa clear ama confusing na zinaweza badilika, na zote ni sawa. Unachofeel ni real na valid hata kama watu hawakuelewi. KITU YA KUFANYA: chagua carefully unamwambia nani, na kwa nafasi ya private isiyo-judge ongea na counsellor ama piga LVCT One2One (1190). Mtu akikutishia, aku-out ama aku-harm kwa sababu hiyo, si sawa — piga Childline 116 (free, 24/7, ukiwa chini ya 18) ama line ya GBV 1195. Hauko peke yako na unastahili respect na safety.$q$,'sheng',null,null,true,40,$j$[{"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "call", "label": "Childline 116", "v": "116"}, {"k": "call", "label": "Line ya GBV 1195", "v": "1195"}]$j$::jsonb),

('gender-identity-sh','identity',$q$Aje kama sifeel kuwa mvulana ama msichana fully?$q$,
 array['gender','identity','trans','mvulana ama msichana'],
 $q$Gender identity ni feeling yako ya ndani ya kuwa mvulana, msichana, zote, hakuna, ama mahali katikati — na kwa watu wengine hai-match jinsia uliyopewa ukizaliwa, kitu ambacho ni experience ya kweli ya binadamu, si trend wala ugonjwa. Unaweza feel hivi strong ama uwe unajiuliza tu, na zote ni sawa; hakuna timeline wala kitu lazima u-decide leo. Kufeel hivi haimaanishi kuna kitu mbaya na wewe. KITU YA KUFANYA: sababu si kila mtu ataelewa, think ni nani safe kuongea naye na uende kwa pace yako; counsellor friendly kwa vijana — ama LVCT One2One (1190) — anaweza kupatia nafasi ya private isiyo-judge. Ukibully-iwa ama kutishiwa, Childline 116 (chini ya 18) na line ya GBV 1195 zinaweza saidia. Feelings zako ni valid.$q$,'sheng',null,null,true,50,$j$[{"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "call", "label": "Childline 116", "v": "116"}]$j$::jsonb),

('sharing-toys-sh','safer-sex',$q$Ni safe ku-share sex toys ama strap-on?$q$,
 array['sex toy','strap on','vibrator','ku-share toys'],
 $q$Ku-share sex toys inaweza kusambaza STI (herpes, HPV, kisonono, chlamydia, hepatitis) na ku-disturb balance inayoleta infections kama BV na fungus, sababu fluids zinabaki kwa toy. Safe zaidi ni kutosha-share; ukisha-share, vaa condom fresh kwa toy na ubadilishe kwa kila mtu, osha toy na maji ya uvuguvugu na sabuni, ikauke, kati ya matumizi, na usiwahi hamisha kutoka anal kwenda uke ama mdomo bila ku-clean na ku-change condom. Tumia lube ya maji ama silicone, na toys body-safe (non-porous). KITU YA KUFANYA: kama umesha-share na uko worried, pima STI kwa clinic friendly, Marie Stopes Kenya (0800 720 005), ama uliza LVCT One2One (1190) — STI mingi haina dalili lakini zinatibika. Hizi rules zinafanya kila ngono kuwa safer.$q$,'sheng','WHO','https://www.who.int/health-topics/sexually-transmitted-infections',true,60,$j$[{"k": "app", "label": "Pata clinic", "v": "#fika"}, {"k": "call", "label": "Marie Stopes", "v": "0800720005"}, {"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "link", "label": "WHO: STIs", "v": "https://www.who.int/health-topics/sexually-transmitted-infections"}]$j$::jsonb),

('drugs-and-sex-sh','harm-reduction',$q$Ni risky ku-mix pombe ama drugs na ngono?$q$,
 array['level','drugs','pombe','ngedo','high'],
 $q$Ku-mix pombe ama drugs na ngono inaongeza risk: kuwa drunk ama high ina-blur judgment, so watu wana-skip condom, wana-misread situation na wana-regret — na muhimu zaidi, mtu aliye drunk ama high sana hawezi kutoa consent ya kweli, maana yake ngono naye si sawa, na rule hiyo inaku-protect wewe pia. Mixtures zingine ni hatari ki-mwili (pombe ama drugs na vidonge vya nguvu, ama ku-mix sedatives). KU-REDUCE HARM: ukikunywa ama utumie, beba condom, linda drink yako, kaa na watu una-trust, kubaliana limits mapema, na kumbuka unaweza stop wakati wowote. KITU YA KUFANYA: kama kitu kilifanyika uki-impaired — ngono bila protection ama usiyo-agree — clinic inaweza toa emergency pill na PEP (ndani ya masaa 72); kwa assault piga GBV 1195 ama police 999, na kuongea piga One2One 1190. Hudaiwi ngono sababu ulinunuliwa drinks.$q$,'sheng',null,null,false,70,$j$[{"k": "call", "label": "Line ya GBV 1195", "v": "1195"}, {"k": "call", "label": "One2One 1190", "v": "1190"}]$j$::jsonb),

('anal-sex-safety-sh','safer-sex',$q$Anal sex ni safe?$q$,
 array['anal','nyuma','backdoor'],
 $q$Anal sex inaweza fanywa safer, lakini ina risk kubwa zaidi ya HIV na STI kuliko aina zingine, sababu lining ni nyembamba na inachanika easy. Ku-lower risk: tumia condom daima na lube ya maji ama silicone mob (sehemu hii haitengenezi lubrication yake), enda pole pole, stop kukiwa na maumivu ama damu; usiwahi enda kutoka anal kwenda uke bila ku-change condom, na usi-douche — inawasha lining na inaongeza risk. Condom ni muhimu pia sababu shahawa ikifika uke inaweza leta mimba. KITU YA KUFANYA: kama unafanya hii, uliza clinic friendly, VCT ama NASCOP kuhusu PrEP na STI test za mara kwa mara, ama piga One2One 1190 — na kama condom ilipasuka, PEP ndani ya masaa 72 bado inaweza zuia HIV.$q$,'sheng','NASCOP','https://www.nascop.or.ke',true,80,$j$[{"k": "app", "label": "Pata clinic", "v": "#fika"}, {"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "link", "label": "NASCOP", "v": "https://www.nascop.or.ke"}]$j$::jsonb),

('what-is-consent-sh','consent',$q$Ni nini hasa inahesabika kama consent?$q$,
 array['consent','pressure','kulazimisha','rape','ndio'],
 $q$Consent ni "ndio" iliyo clear, ya hiari na ya enthusiasm — na inahesabika tu mtu akiwa sober, awake, age ya kutosha, na bila pressure, vitisho ama hofu. Ni specific (ndio kwa kitu kimoja si kwa kila kitu), inaendelea (unaweza badilisha mind wakati wowote), na inahitajika kila mara, hata na bae ama mwenzi wa ndoa. Silence, kukubali tu, ama "ndio" ya kulazimishwa si consent. RIGHTS ZAKO: ngono bila consent ni crime Kenya chini ya Sexual Offences Act 2006, na ngono na mtu chini ya miaka 18 ni defilement, bila kujali "agreement". KITU YA KUFANYA: kama hii imekutokea, si kosa lako — enda clinic ama hospitali haraka (ndani ya masaa 72 wanaweza toa PEP na emergency pill na ku-fill forms za PRC na P3 za evidence), piga GBV 1195, Childline 116 ukiwa chini ya 18, ama police 999. Help iko, na ku-report ni choice yako.$q$,'sheng',null,null,false,90,$j$[{"k": "call", "label": "Line ya GBV 1195", "v": "1195"}, {"k": "call", "label": "Childline 116", "v": "116"}, {"k": "call", "label": "Polisi 999", "v": "999"}, {"k": "app", "label": "Pata clinic", "v": "#fika"}]$j$::jsonb),

('after-unprotected-sex-sh','emergency',$q$Nime-fanya ngono bila protection — nifanye aje sahii?$q$,
 array['bila protection','condom ilipasuka','kuzuia mimba','pep','p2','postinor'],
 $q$Fanya haraka — options zako zina-work best ndani ya masaa. KUZUIA MIMBA: emergency pill (inauzwa Kenya bila prescription kwa chemist kama P2, Postinor-2 ama Ecee-2) ina-work best ndani ya masaa 72; aina zingine na copper IUD (inawekwa clinic) hadi masaa 120 (siku 5) — mapema ni poa. KUZUIA HIV: PEP ni dawa za course fupi lazima zianze ndani ya masaa 72 — enda hospitali, health centre ama VCT uombe kwa jina. PA KWENDA: chemist yoyote kwa emergency pill; VCT, hospitali ama Marie Stopes Kenya (0800 720 005) kwa PEP, EC na STI test; ama piga LVCT One2One (1190) ama NASCOP Ushauri (0800 724 848). Kama period ita-delay, pima mimba baada ya wiki tatu. Huhitaji permission ya mzazi kuuliza.$q$,'sheng','NASCOP','https://www.nascop.or.ke',false,100,$j$[{"k": "app", "label": "Pata clinic", "v": "#fika"}, {"k": "call", "label": "Marie Stopes", "v": "0800720005"}, {"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "call", "label": "NASCOP Ushauri", "v": "0800724848"}]$j$::jsonb),

('protect-from-hiv-sh','hiv',$q$Naweza jikinga aje na HIV?$q$,
 array['hiv','prep','kujikinga','ukimwi','u=u'],
 $q$Uko na tools kadhaa strong, na ku-combine ina-work best. Condom ukitumia vizuri kila mara ni effective sana na pia inazuia STI zingine na mimba. PrEP — kidonge cha kila siku kinachotolewa free kupitia clinic za NASCOP — kinaweza zuia HIV kabla ya exposure kama uko kwa risk zaidi. Uki-exposed, PEP iliyoanza ndani ya masaa 72 bado inaweza zuia infection. Na U=U: mtu anayeishi na HIV mwenye viral load isiyoonekana hawezi ku-transmit ki-ngono. PA KWENDA: pata test free na confidential (ama self-test kit kutoka chemist) na uliza kuhusu PrEP kwa clinic friendly ama VCT; kwa maswali piga LVCT One2One (1190) ama NASCOP Ushauri (0800 724 848). Kujua status yako ni haraka na free.$q$,'sheng','NASCOP','https://www.nascop.or.ke',false,110,$j$[{"k": "app", "label": "Pata clinic", "v": "#fika"}, {"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "call", "label": "NASCOP Ushauri", "v": "0800724848"}, {"k": "link", "label": "NASCOP", "v": "https://www.nascop.or.ke"}]$j$::jsonb),

('am-i-pregnant-sh','pregnancy',$q$Nitajua aje kama niko na mimba?$q$,
 array['mimba','sijaona period','pregnancy test','period imechelewa'],
 $q$Dalili ya kwanza ni period ku-miss ama ku-delay sana, pengine na maziwa yakiuma, nausea, uchovu, kukojoa mara mingi, ama spotting kidogo — lakini stress, ugonjwa na hormones zinaweza leta hizi, so dalili peke yake hazi-confirm. Njia pekee ya uhakika ni test: urine kits ni rahisi kwa chemist yoyote Kenya, na ni accurate zaidi kuanzia siku period inatarajiwa (ama wiki tatu baada ya ngono bila protection); tumia urine ya asubuhi, na kama ni negative lakini period haiji, pima tena baada ya wiki. KITU YA KUFANYA: result yoyote, clinic friendly ama Marie Stopes Kenya (0800 720 005) inaweza kueleza choices zako kwa private na bila judgment, na LVCT One2One (1190) iko kuku-listen. Hauko peke yako.$q$,'sheng',null,null,false,120,$j$[{"k": "app", "label": "Pata clinic", "v": "#fika"}, {"k": "call", "label": "Marie Stopes", "v": "0800720005"}, {"k": "call", "label": "One2One 1190", "v": "1190"}]$j$::jsonb),

('porn-vs-reality-sh','media',$q$Je, ngono halisi iko kama ninaona kwa porn?$q$,
 array['porn','ponografia','xvideos','real info'],
 $q$Hapana — porn ni entertainment iliyo-produced, si documentary. Actors wanachaguliwa kwa looks, scenes zina-script, zina-light na ku-edit, miili ime-alter ki-upasuaji, na "stamina" ni cuts na wakati zingine dawa. Ngono halisi iko slower, ya aibu kidogo, quiet na varied — miili ya kawaida, si kila mtu ana-finish, na consent na communication ambazo porn ina-skip ndio zina-make iwe poa. PA KUPATA INFO HALISI: kwa info sahihi na bila aibu kuhusu mwili, ngono, consent na relationships, uliza hapa Ukweli, ongea na nurse ama counsellor kwa clinic friendly, ama piga LVCT One2One free kwa 1190; sources za kuaminika ni WHO sexual-health pages. Jihadhari na "experts" wa socials — clinic ya kweli haita-ku-judge wala kuku-lie.$q$,'sheng',null,null,false,130,$j$[{"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "app", "label": "Uliza kwa siri", "v": "#ask"}, {"k": "link", "label": "WHO: sexual health", "v": "https://www.who.int/health-topics/sexual-health"}]$j$::jsonb),

('pressured-for-nudes-sh','safety',$q$Mtu ananipressure nimtumie nudes.$q$,
 array['nudes','nude','sexting','kutuma pics','sextortion','report'],
 $q$Hudai mtu yoyote picha — si bae, si mkubwa, si anaye-promise love, doo ama siri — na respect ya kweli ni kusikia "no" mara ya kwanza. Picha ikitoka kwa simu una-lose control yote, hata kwa apps za "ku-disappear". NI CRIME: ku-pressure, ku-threaten ama ku-share pics za private za mtu Kenya ni offence chini ya Computer Misuse and Cybercrimes Act 2018, na mtoto akihusika pia chini ya Sexual Offences Act 2006 na Children Act — anayefanya ndiye wrong, si wewe, hata kama uli-send kitu awali. KITU YA KUFANYA: usi-send zaidi na usilipe (kulipa inaleta demands zaidi); save screenshots kama evidence, mu-block, na report — piga Childline 116 (free, 24/7, ukiwa chini ya 18), ama report kwa station yoyote ya police ama DCI (cybercrime unit); kwa support piga GBV 1195. Uko na right ya kusema no na right ya kupata help.$q$,'sheng',null,null,false,140,$j$[{"k": "call", "label": "Childline 116", "v": "116"}, {"k": "call", "label": "Line ya GBV 1195", "v": "1195"}, {"k": "app", "label": "Uliza kwa siri", "v": "#ask"}]$j$::jsonb)
